"""Internal Linux parser process. Input/output paths are generated by the server."""

import json
import resource
import sys
from pathlib import Path
from typing import Any

from app.ingestion.text_processor import section_kind


def main() -> None:
    resource.setrlimit(resource.RLIMIT_AS, (768 * 1024 * 1024, 768 * 1024 * 1024))
    resource.setrlimit(resource.RLIMIT_CPU, (20, 21))
    resource.setrlimit(resource.RLIMIT_FSIZE, (20 * 1024 * 1024, 20 * 1024 * 1024))
    resource.setrlimit(resource.RLIMIT_NOFILE, (64, 64))
    import pymupdf

    source, output, max_pages, max_chars, mode = sys.argv[1:]
    result: dict[str, Any] = {}
    try:
        with pymupdf.open(source) as document:  # type: ignore[no-untyped-call]
            if not document.is_pdf or document.needs_pass:
                result = {
                    "error": "encrypted_or_invalid_pdf",
                    "message": "Only unencrypted PDF documents can be processed.",
                }
            elif not 1 <= document.page_count <= int(max_pages):
                result = {"error": "page_limit", "message": "PDF exceeds the configured page count limit."}
            else:
                pages, issues, total = [], [], 0
                if document.is_repaired:
                    issues.append("PDF required structural repair; manual review is required.")
                if document.embfile_count():
                    issues.append("Embedded attachments were ignored and were not opened.")
                if mode == "parse":
                    for number, page in enumerate(document, 1):
                        raw = page.get_text("dict", sort=True)
                        blocks, text_parts, page_issues = [], [], []
                        for index, block in enumerate(raw.get("blocks", [])):
                            if block.get("type") != 0:
                                continue
                            spans = [
                                span for line in block.get("lines", []) for span in line.get("spans", [])
                            ]
                            text = "\n".join(
                                "".join(span.get("text", "") for span in line.get("spans", []))
                                for line in block.get("lines", [])
                            ).strip()
                            if not text:
                                continue
                            text = text.replace("\x00", "\ufffd")
                            total += len(text)
                            if total > int(max_chars):
                                raise OverflowError
                            sizes = [span.get("size", 0) for span in spans]
                            heading = len(text) < 180 and (
                                max(sizes, default=0) >= 13
                                or any(span.get("flags", 0) & 16 for span in spans)
                            )
                            blocks.append(
                                {
                                    "section_identifier": f"p{number}-b{index}",
                                    "text": text,
                                    "bbox": list(block["bbox"]),
                                    "extraction_method": "pymupdf-text-block",
                                    "kind": section_kind(text),
                                    "heading": text if heading else None,
                                }
                            )
                            text_parts.append(text)
                        page_text = "\n\n".join(text_parts)
                        if not page_text.strip():
                            page_issues.append(
                                "No extractable text; image-only or blank page. OCR/manual review required."
                            )
                        if "\ufffd" in page_text or page_text.count("\x00"):
                            page_issues.append("Possible corrupted glyphs; manual review required.")
                        try:
                            tables = page.find_tables()
                            for index, table in enumerate(tables.tables[:20]):
                                rows = table.extract()
                                table_text = "\n".join(" | ".join(cell or "" for cell in row) for row in rows)
                                if table_text.strip() and len(table_text) + total <= int(max_chars):
                                    total += len(table_text)
                                    blocks.append(
                                        {
                                            "section_identifier": f"p{number}-table{index}",
                                            "text": table_text,
                                            "bbox": list(table.bbox),
                                            "extraction_method": "pymupdf-table",
                                            "kind": section_kind(table_text),
                                            "heading": None,
                                        }
                                    )
                        except Exception:
                            page_issues.append(
                                "Table detection was incomplete; verify the original page manually."
                            )
                        pages.append(
                            {
                                "page_number": number,
                                "text_content": page_text,
                                "blocks": blocks,
                                "issues": page_issues,
                            }
                        )
                result = {
                    "page_count": document.page_count,
                    "metadata": {
                        key: str(value).replace("\x00", "")[:1000]
                        for key, value in (document.metadata or {}).items()
                        if value
                    },
                    "pages": pages,
                    "issues": issues,
                }
    except OverflowError:
        result = {
            "error": "text_limit",
            "message": "Extracted PDF text exceeds the configured resource limit.",
        }
    except Exception:
        result = {"error": "malformed_pdf", "message": "PDF could not be safely parsed."}
    Path(output).write_text(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
